-- ============================================================
-- NCR-OMS bulk order-history import
-- Generated by Claude (Anthropic) for: Meesho, Flipkart, Amazon,
-- Snapdeal, Myntra "DOMESTIC_ORDER_DATA_2026-27" exports.
-- Rows: 4119 orders / 4695 items / 4119 shipments / 80 returns
--
-- RUN THE FILES IN THIS DIRECTORY IN FILENAME ORDER (00_..., 01_..., ...,
-- 99_finalize.sql last) -- each one is small enough for the Supabase SQL
-- editor. Every file is independently safe to re-run if something fails
-- partway; re-running the whole sequence never duplicates data.
--
-- READ BEFORE RUNNING (also see the chat write-up / project doc for full detail):
--  1. Brand/company is resolved per order from product-title text.
--     Orders with no reliable signal (all of Meesho, most of Amazon,
--     a handful of Flipkart/Snapdeal) go under a 4th pseudo-company
--     "UNASSIGNED - NEEDS BRAND REVIEW" rather than being guessed.
--     See the review queries in 99_finalize.sql to reassign them.
--  2. No inventory_ledger stock-reservation rows are written for this
--     historical backfill (these orders already happened; reserving
--     stock against them would send on-hand deeply negative). If you
--     want current on-hand stock to reflect a starting point, use the
--     Company & Setup / Party Master "Stock In" flow for an opening
--     balance instead.
--  3. marketplace_accounts created here get a PLACEHOLDER encrypted
--     credentials blob (this script has no access to the live
--     ENCRYPTION_MASTER_KEY) - fine for CSV-history, but re-enter
--     real credentials via Company & Setup before using any live
--     marketplace API connector on these accounts.
--  4. Staging tables are prefixed _import_stg_ and are left in place
--     after 99_finalize.sql runs (harmless) -- drop them yourself
--     whenever convenient, see the commented-out DROP block at the
--     bottom of 99_finalize.sql.
-- ============================================================

BEGIN;

-- Auto-assign memory: a SKU code we've resolved with confidence once
-- (from a product title mentioning the brand) is remembered here, so a
-- future import of the same code does not need to ask again.
CREATE TABLE IF NOT EXISTS import_brand_hints (
  id serial PRIMARY KEY,
  marketplace_sku varchar(200) NOT NULL,
  brand_name varchar(150) NOT NULL,
  company_legal_name varchar(200) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(marketplace_sku, brand_name)
);

-- Ensure the 3 real companies + the review-queue pseudo-company exist.
-- (matches scripts/seed-companies.ts legalNames exactly where real)
DO $$
DECLARE
  v_company_id integer;
  v_brand_id integer;
  v_wh_id integer;
BEGIN
  -- NYKO_MART
  SELECT id INTO v_company_id FROM companies WHERE legal_name = 'Nyko Mart' LIMIT 1;
  IF v_company_id IS NULL THEN
  END IF;
  SELECT id INTO v_brand_id FROM brands WHERE company_id = v_company_id AND name = 'Vardhamati' LIMIT 1;
  IF v_brand_id IS NULL THEN
  END IF;
  SELECT id INTO v_wh_id FROM warehouses WHERE company_id = v_company_id AND is_default = true LIMIT 1;
  IF v_wh_id IS NULL THEN
  END IF;

  -- RUGARA
  SELECT id INTO v_company_id FROM companies WHERE legal_name = 'Rugara' LIMIT 1;
  IF v_company_id IS NULL THEN
  END IF;
  SELECT id INTO v_brand_id FROM brands WHERE company_id = v_company_id AND name = 'Arvagam' LIMIT 1;
  IF v_brand_id IS NULL THEN
  END IF;
  SELECT id INTO v_wh_id FROM warehouses WHERE company_id = v_company_id AND is_default = true LIMIT 1;
  IF v_wh_id IS NULL THEN
  END IF;

  -- CASA_ARRA
  SELECT id INTO v_company_id FROM companies WHERE legal_name = 'Casa Arra' LIMIT 1;
  IF v_company_id IS NULL THEN
  END IF;
  SELECT id INTO v_brand_id FROM brands WHERE company_id = v_company_id AND name = 'Kanjush' LIMIT 1;
  IF v_brand_id IS NULL THEN
  END IF;
  SELECT id INTO v_wh_id FROM warehouses WHERE company_id = v_company_id AND is_default = true LIMIT 1;
  IF v_wh_id IS NULL THEN
  END IF;

  -- UNASSIGNED
  SELECT id INTO v_company_id FROM companies WHERE legal_name = 'UNASSIGNED - NEEDS BRAND REVIEW' LIMIT 1;
  IF v_company_id IS NULL THEN
  END IF;
  SELECT id INTO v_brand_id FROM brands WHERE company_id = v_company_id AND name = 'Unassigned' LIMIT 1;
  IF v_brand_id IS NULL THEN
  END IF;
  SELECT id INTO v_wh_id FROM warehouses WHERE company_id = v_company_id AND is_default = true LIMIT 1;
  IF v_wh_id IS NULL THEN
  END IF;

END $$;

-- Ensure a marketplace_account exists per (brand, marketplace) this
-- import actually needs. Reuses ANY existing active account for that
-- brand+marketplace (regardless of label) so we never split one
-- brand's order history across two accounts; only creates a new
-- 'Bulk CSV Import' account when none exists at all.
DO $$
DECLARE
  v_company_id integer;
  v_brand_id integer;
  v_acct_id integer;
BEGIN
  -- ARVAGAM / AMAZON_IN
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Rugara' AND b.name='Arvagam' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'AMAZON_IN'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'AMAZON_IN'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- ARVAGAM / FLIPKART
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Rugara' AND b.name='Arvagam' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'FLIPKART'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'FLIPKART'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- ARVAGAM / MYNTRA
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Rugara' AND b.name='Arvagam' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'MYNTRA'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'MYNTRA'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- ARVAGAM / SNAPDEAL
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Rugara' AND b.name='Arvagam' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'SNAPDEAL'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'SNAPDEAL'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- KANJUSH / FLIPKART
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Casa Arra' AND b.name='Kanjush' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'FLIPKART'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'FLIPKART'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- KANJUSH / SNAPDEAL
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Casa Arra' AND b.name='Kanjush' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'SNAPDEAL'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'SNAPDEAL'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- UNASSIGNED / AMAZON_IN
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='UNASSIGNED - NEEDS BRAND REVIEW' AND b.name='Unassigned' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'AMAZON_IN'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'AMAZON_IN'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- UNASSIGNED / MEESHO
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='UNASSIGNED - NEEDS BRAND REVIEW' AND b.name='Unassigned' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'MEESHO'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'MEESHO'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- VARDHAMATI / AMAZON_IN
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Nyko Mart' AND b.name='Vardhamati' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'AMAZON_IN'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'AMAZON_IN'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- VARDHAMATI / FLIPKART
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Nyko Mart' AND b.name='Vardhamati' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'FLIPKART'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'FLIPKART'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

  -- VARDHAMATI / SNAPDEAL
  SELECT b.id, b.company_id INTO v_brand_id, v_company_id FROM brands b JOIN companies c ON c.id=b.company_id WHERE c.legal_name='Nyko Mart' AND b.name='Vardhamati' LIMIT 1;
  SELECT id INTO v_acct_id FROM marketplace_accounts WHERE brand_id = v_brand_id AND marketplace = 'SNAPDEAL'::marketplace AND is_active = true LIMIT 1;
  IF v_acct_id IS NULL THEN
    VALUES (v_brand_id, 'SNAPDEAL'::marketplace, 'Bulk CSV Import', 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==');
  END IF;

END $$;

-- Seed the auto-assign memory with the 245 SKU codes this
-- run resolved with confidence (product title mentioned the brand,
-- and no other brand's title ever used the same code).
ON CONFLICT (marketplace_sku, brand_name) DO NOTHING;

-- Staging tables. PERSISTENT (not TEMP) because each numbered file in
-- this folder is run as a separate SQL editor submission/connection --
-- a TEMP table would vanish before the next file runs. Prefixed and
-- harmless to leave in place; 99_finalize.sql has an optional DROP.
CREATE TABLE IF NOT EXISTS _import_stg_orders (
  marketplace varchar(20), marketplace_order_id text, brand_key text, status text, fulfillment_type text,
  invoice_number text, invoice_date timestamptz, ordered_at timestamptz, verified_at timestamptz, raw_json text
);
CREATE TABLE IF NOT EXISTS _import_stg_items (
  marketplace varchar(20), marketplace_order_id text, line_id text, marketplace_sku text, product_title text,
  variant_size text, quantity integer, unit_price numeric, mrp numeric, shipping_charge numeric,
  invoice_amount numeric, cgst numeric, sgst numeric, igst numeric, tax_rate numeric, hsn text, settlement_est numeric
);
CREATE TABLE IF NOT EXISTS _import_stg_shipments (
  marketplace varchar(20), marketplace_order_id text, shipment_id text, package_id text, packet_id text,
  awb_number text, carrier text, tracking_url text, service_level text, recipient_name text,
  recipient_address1 text, recipient_address2 text, recipient_city text, recipient_state text, recipient_pincode text,
  dispatch_start timestamptz, dispatch_end timestamptz, shipped_at timestamptz, delivered_at timestamptz,
  pkg_length numeric, pkg_breadth numeric, pkg_height numeric, pkg_weight numeric
);
CREATE TABLE IF NOT EXISTS _import_stg_returns (
  marketplace varchar(20), marketplace_order_id text, status text, return_type text, reason text
);
-- Clear out any partial data from a previous attempt so re-running
-- this whole file sequence from 00 never double-stages rows.
TRUNCATE _import_stg_orders, _import_stg_items, _import_stg_shipments, _import_stg_returns;

COMMIT;
